def _waypoint(x, y):
    # Ensure y is within gate y range when in gate x range
    if G1_X - 0.5 <= x <= G1_X + 0.5:
        # Adjust y to be within Gate 1's y range if needed
        if y > G1_Y + 0.5:
            return (G1_X, G1_Y + 0.5)
        elif y < G1_Y - 0.5:
            return (G1_X, G1_Y - 0.5)
    if G2_X - 0.5 <= x <= G2_X + 0.5:
        # Adjust y to be within Gate 2's y range if needed
        if y > G2_Y + 0.5:
            return (G2_X, G2_Y + 0.5)
        elif y < G2_Y - 0.5:
            return (G2_X, G2_Y - 0.5)
